<script setup lang="ts">
defineProps<{orders:any[];disabled?:boolean}>()
const emit=defineEmits(['remove'])
const labels:Record<string,string>={accept:'Aceite agendado',cancel:'Cancelamento agendado',start:'Início da missão agendado',withdraw:'Retirada agendada',decision:'Resposta agendada',upgrade:'Melhoria agendada',maintenance:'Reparo agendado',resupply:'Reposição agendada',purchase:'Compra agendada',hire:'Contratação agendada',renew:'Renovação agendada',activity:'Atividade agendada',activity_cancel:'Interrupção agendada',squad_create:'Equipe planejada',squad_update:'Formação planejada',squad_member_add:'Integrante planejado',squad_training:'Treinamento agendado'}
</script>
<template><div v-if="orders?.length" class="scheduled-orders"><div v-for="order in orders" :key="order.id" class="scheduled-order"><div role="status"><strong>{{labels[order.kind]||'Ação agendada'}}</strong><small>{{order.title}}<template v-if="order.kind==='purchase'"> · {{order.command.quantity}} unidade(s)</template></small><small>{{order.previewText||'O primeiro avanço já conta para a execução.'}}</small></div><button type="button" class="secondary" :disabled="disabled" :aria-label="'Remover ordem: '+order.title" @click="emit('remove',order.id)">Remover</button></div></div></template>
